<script setup lang="ts">
import { computed,ref,watch } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { useI18n } from 'vue-i18n';import { api } from '@/api';import { useMerchantStore } from '@/stores/merchant';import { fixedMinor } from '@/shared/stored-value-form';import { idempotencyKey } from '@shared/net/http-client';import { money } from '@shared/utils/money';import type { SvContext,SvPlanCreate } from '@/api/stored-value-types';
const {t}=useI18n();const merchant=useMerchantStore();const context=ref<SvContext|null>(null);const name=ref('');const paid=ref('');const bonus=ref('0');const review=ref(false);const busy=ref(false);const error=ref('');const failed=ref(false);const pending=ref<{body:SvPlanCreate;key:string}|null>(null);let store='',storage='';
const locked=computed(()=>busy.value||!!pending.value||store!==merchant.storeNo);const total=computed(()=>{try{return context.value?money(fixedMinor(paid.value,context.value.currencyScale)+fixedMinor(bonus.value,context.value.currencyScale),context.value.currency):'—';}catch{return '—';}});
function body():SvPlanCreate {if(!context.value||!name.value.trim())throw Error(t('storedValue.required'));const p=fixedMinor(paid.value,context.value.currencyScale),b=fixedMinor(bonus.value,context.value.currencyScale);if(p<=0||!Number.isSafeInteger(p+b))throw Error(t('storedValue.invalidAmount'));return {storeNo:store,name:name.value.trim(),currency:context.value.currency,paidAmountMinor:p,bonusAmountMinor:b};}
function next(){try{body();review.value=true;error.value='';}catch{error.value=t('storedValue.invalidAmount');}}
async function load(){failed.value=false;try{await merchant.ensureStores();store=merchant.storeNo;storage=`sv.plan:${merchant.profile?.merchantNo}:${store}`;const c=await api.mSvContext(store);if(store!==merchant.storeNo)return;context.value=c;const saved=uni.getStorageSync(storage);if(saved){const v=JSON.parse(String(saved));if(v.body?.storeNo===store&&typeof v.key==='string'){pending.value=v;name.value=v.body.name;paid.value=String(v.body.paidAmountMinor/10**c.currencyScale);bonus.value=String(v.body.bonusAmountMinor/10**c.currencyScale);review.value=true;}}}catch(e){failed.value=true;error.value=(e as Error).message;}}
async function save(){if(busy.value||store!==merchant.storeNo||!merchant.can('pay:sv:plan:manage'))return;busy.value=true;error.value='';try{if(!pending.value){const c=body();pending.value={body:c,key:idempotencyKey()};}uni.setStorageSync(storage,JSON.stringify(pending.value));const result=await api.mSvCreatePlan(pending.value.body,pending.value.key);uni.removeStorageSync(storage);pending.value=null;if(store===merchant.storeNo)uni.redirectTo({url:`/pages/stored-value-plan-detail/index?planNo=${encodeURIComponent(result.planNo)}`});}catch(e){const code=(e as {code?:number}).code;if(code&&[10400,10403,10404,10409,70006,40040].includes(code)){uni.removeStorageSync(storage);pending.value=null;}error.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>merchant.storeNo,()=>{context.value=null;error.value=t('storedValue.leaveStore');});onLoad(()=>void load());
</script>
<template><sh-scaffold :title-suffix="merchant.multiStore ? merchant.currentStore?.name : ''" title-key="storedValue.newPlan" :denied="!merchant.can('pay:sv:plan:manage')" :failed="failed" :pending="!context&&!failed" @retry="load">
 <view v-if="context&&!review" class="sh-card sv-card">
  <view class="field"><text class="field__label">{{t('storedValue.planName')}}</text><input v-model="name" class="field__input" :disabled="locked" maxlength="100"/></view>
  <view class="field"><text class="field__label">{{t('storedValue.paid')}} · {{context.currency}}</text><input v-model="paid" class="field__input sh-num" type="digit" :disabled="locked"/></view>
  <view class="field"><text class="field__label">{{t('storedValue.bonus')}} · {{context.currency}}</text><input v-model="bonus" class="field__input sh-num" type="digit" :disabled="locked"/></view>
  <sh-kv :label="t('storedValue.total')" between><text class="txt-price sh-num">{{total}}</text></sh-kv>
 </view>
 <view v-if="review&&context" class="sh-card sv-card"><text class="txt-title">{{name}}</text><sh-kv :label="t('storedValue.paid')" between>{{money(pending?.body.paidAmountMinor??fixedMinor(paid,context.currencyScale),context.currency)}}</sh-kv><sh-kv :label="t('storedValue.bonus')" between>{{money(pending?.body.bonusAmountMinor??fixedMinor(bonus,context.currencyScale),context.currency)}}</sh-kv><sh-kv :label="t('storedValue.total')" between><text class="txt-price sh-num">{{total}}</text></sh-kv></view>
 <text v-if="error" class="sh-hint">{{error}}</text><text v-if="pending" class="sh-hint">{{t('storedValue.networkUnknown')}}</text>
 <sh-actionbar v-if="context"><view class="sh-row"><button v-if="review&&!pending" class="sh-btn sh-btn--soft" :disabled="busy" @tap="review=false">{{t('storedValue.back')}}</button><button class="sh-btn" :loading="busy" :disabled="busy||store!==merchant.storeNo" @tap="review?save():next()">{{t(review?'storedValue.create':'storedValue.next')}}</button></view></sh-actionbar>
</sh-scaffold></template>
